#!/usr/bin/env python3

"""Report account balances from a ledger file."""

import sys


def to_cents(amount):
    whole, fraction = amount.split(".")
    return int(whole) * 100 + int(fraction)


def format_cents(cents):
    sign = "-" if cents < 0 else ""
    cents = abs(cents)
    return f"{sign}{cents // 100}.{cents % 100:02d}"


def by_balance_then_name(entry):
    account, balance = entry
    return (-balance, account.encode("utf-8"))


def read_ledger(path):
    text = open(path, "rb").read().decode("utf-8")
    return text.splitlines()


def main():
    lines = read_ledger(sys.argv[1])
    n = int(lines[0].split()[1])

    balances = {}
    for index in range(n):
        account, kind, amount = lines[1 + index].split()
        if kind == "credit":
            signed = to_cents(amount)
        elif kind == "debit":
            signed = -to_cents(amount)
        else:
            print(f"ERROR line {index + 1}")
            return
        balances[account] = balances.get(account, 0) + signed

    total = 0
    for account, balance in sorted(balances.items(), key=by_balance_then_name):
        print(f"{account} {format_cents(balance)}")
        total = total + balance
    print(f"TOTAL {format_cents(total)}")


if __name__ == "__main__":
    main()
